import{_ as o,o as r,c as t,a0 as a}from"./chunks/framework.BYCjvD8D.js";const u=JSON.parse('{"title":"Research methodology","description":"","frontmatter":{},"headers":[],"relativePath":"methodology.md","filePath":"methodology.md"}'),n={name:"methodology.md"};function i(s,e,l,d,c,p){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="research-methodology" tabindex="-1">Research methodology <a class="header-anchor" href="#research-methodology" aria-label="Permalink to &quot;Research methodology&quot;">​</a></h1><h2 id="provenance-and-integrity" tabindex="-1">Provenance and integrity <a class="header-anchor" href="#provenance-and-integrity" aria-label="Permalink to &quot;Provenance and integrity&quot;">​</a></h2><p>This project is inspired by the original 2015 public demonstration. It is a modern <strong>retrospective educational implementation</strong>, not a contemporaneous artifact from Rock AI in 2016.</p><p>Historical records, original author&#39;s work and modern reconstruction results should be kept separate in the professional research portfolio and doctoral application.</p><h2 id="experimental-controls" tabindex="-1">Experimental controls <a class="header-anchor" href="#experimental-controls" aria-label="Permalink to &quot;Experimental controls&quot;">​</a></h2><ul><li>Fix pseudo-random seeds and episode limits for reproducibility.</li><li>Compare against random button policies, always-right baselines and simple hand-coded controllers.</li><li>Run multiple independent seeds and report median, variance, convergence rates and wall-clock time.</li><li>Validate on held-out level layouts. Training on one fixed course alone is insufficient evidence of generalisation.</li><li>Record number of generations, genomes evaluated, best fitness, best progress, completion rate, network complexity and hardware/browser details.</li><li>Test that structural evolution improves on weight-only evolution through ablations.</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>The neuroevolution loop runs in a <strong>Web Worker on the browser&#39;s CPU</strong>. The network visualization uses <strong>Three.js WebGPURenderer</strong> when WebGPU is supported, or its WebGL alternative when unavailable. GPU rendering does <strong>not</strong> imply GPU-based network training.</p><p>Before introducing WebGPU compute shaders for training, benchmark fitness evaluation and genome processing, which are branch-heavy and highly variable in structure.</p><h2 id="intellectual-property" tabindex="-1">Intellectual property <a class="header-anchor" href="#intellectual-property" aria-label="Permalink to &quot;Intellectual property&quot;">​</a></h2><p>No Nintendo game assets, music, source ROMs, or emulator dumps are included. Do not copy SethBling&#39;s published Lua script into this repository: its header discourages redistribution. Refer to the original externally and implement from published principles with independent source.</p><p>The reference Python project is studied as another design, not copied into the new project. This repository&#39;s original implementation is covered by its own LICENSE.</p>',12)])])}const m=o(n,[["render",i]]);export{u as __pageData,m as default};
